import{_ as n,c as a,o as s,ag as t}from"./chunks/framework.Vyheyqg9.js";const h=JSON.parse('{"title":"A sustainable study cycle and progress record","description":"","frontmatter":{},"headers":[],"relativePath":"learner-guide/progress.md","filePath":"learner-guide/progress.md"}'),r={name:"learner-guide/progress.md"};function i(o,e,d,p,c,l){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="a-sustainable-study-cycle-and-progress-record" tabindex="-1">A sustainable study cycle and progress record <a class="header-anchor" href="#a-sustainable-study-cycle-and-progress-record" aria-label="Permalink to “A sustainable study cycle and progress record”">​</a></h1><p><a href="./">Guide home</a> · <a href="./../practice/learning-projects.html#retain-a-real-evidence-record">Existing evidence requirements</a></p><p>Read a bounded section → predict or trace a concrete example → attempt independently → run meaningful checks → investigate one failure → record evidence → revisit the explanation. A loop ends with a smaller uncertainty or a better counterexample, not necessarily with a completed project. Save a working increment before widening scope. Start the next bounded exercise once its inputs and invariants make sense; defer later service/provider/deployment requirements until integration.</p><h2 id="keep-five-statuses-separate" tabindex="-1"><span class="hub-section-number">1 </span>Keep five statuses separate <a class="header-anchor" href="#keep-five-statuses-separate" aria-label="Permalink to “1 Keep five statuses separate”">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>What it means</th><th>What it does not prove</th></tr></thead><tbody><tr><td>Material read</td><td>You read named sections and recorded a question/summary</td><td>Implementation or recall</td></tr><tr><td>Exercise attempted</td><td>Your own revision exists, with a stated contract</td><td>Correct behavior</td></tr><tr><td>Checks passed</td><td>Named commands/cases passed on that revision</td><td>Unchecked boundaries, independent explanation or production readiness</td></tr><tr><td>Concept demonstrated independently</td><td>You explain/trace/modify it without following the worked solution and defend a counterexample</td><td>Universal mastery</td></tr><tr><td>Remaining uncertainty</td><td>Explicit unresolved behavior and next investigation</td><td>A failure of the study process</td></tr></tbody></table><p>Do not infer a later status from an earlier one. Reference verification belongs in the reference ledger, not your learner record. All fields below intentionally start outstanding/unrecorded.</p><h2 id="copy-this-template-into-your-own-evidence-notebook" tabindex="-1"><span class="hub-section-number">2 </span>Copy this template into your own evidence notebook <a class="header-anchor" href="#copy-this-template-into-your-own-evidence-notebook" aria-label="Permalink to “2 Copy this template into your own evidence notebook”">​</a></h2><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Track / existing assignment ID / bounded milestone:</span></span>
<span class="line"><span>Lesson links and sections:</span></span>
<span class="line"><span>Material read: outstanding; actual sections/date/own explanation:</span></span>
<span class="line"><span>Exercise attempted: outstanding; own directory/revision and chosen contract:</span></span>
<span class="line"><span>Checks passed: unrecorded; command/case, expected vs observed, exit result:</span></span>
<span class="line"><span>Concept demonstrated independently: unrecorded; trace/change/explanation:</span></span>
<span class="line"><span>Remaining uncertainty / next concrete action:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Reading prerequisites satisfied / still uncertain:</span></span>
<span class="line"><span>Implementation dependencies satisfied / outstanding:</span></span>
<span class="line"><span>Source revision and runtime/compiler/lock/config identities:</span></span>
<span class="line"><span>Synthetic input bytes / seed / schedule / workload:</span></span>
<span class="line"><span>Negative case that detected a real defect:</span></span>
<span class="line"><span>Correction and retest tied to final revision:</span></span>
<span class="line"><span>Resources opened / owner / close and natural-exit observation:</span></span>
<span class="line"><span>Safe evidence files (no credentials/private logs):</span></span>
<span class="line"><span>Boundary-specific evidence (UI, SQL race, receipt, restore, etc.):</span></span>
<span class="line"><span>Performed checks versus unperformed environments:</span></span>
<span class="line"><span>Reviewer/approval outcome: not performed unless actually observed</span></span>
<span class="line"><span>Next milestone and observable entry criterion:</span></span></code></pre></div><p>Record exact case outcomes rather than “done.” A screenshot supports visible state, not transaction isolation. A mock supports adapter contracts, not live provider quality. A finished build supports those candidate bytes, not a later edit. Keep unknown costs/outcomes unknown; do not convert them into zeros or success.</p>`,9)])])}const m=n(r,[["render",i]]);export{h as __pageData,m as default};
